// Creating a Promise
let promise = new Promise((resolve, reject) => {
  let success = true;
  if (success) {
    resolve("Data loaded!");  // → fulfilled
  } else {
    reject(new Error("Failed"));  // → rejected
  }
});

// Handling the result
promise
  .then(value => console.log(value))      // "Data loaded!"
  .catch(error => console.error(error));

// Wrapping setTimeout in a Promise
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

delay(2000).then(() => console.log("2 seconds passed!"));

// Wrapping an error-first callback
function fetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id > 0) {
        resolve({ id, name: "User " + id });
      } else {
        reject(new Error("Invalid ID"));
      }
    }, 100);
  });
}

fetchUser(1).then(console.log);  // { id: 1, name: "User 1" }
fetchUser(-1).catch(console.error);  // Error: Invalid ID

