function fetchUser(id) {
  return new Promise(resolve => {
    setTimeout(() => resolve({ id, name: "Alex" }), 100);
  });
}

function fetchPosts(userId) {
  return new Promise(resolve => {
    setTimeout(() => resolve(["Post 1", "Post 2"]), 100);
  });
}

fetchUser(1)
  .then(user => {
    console.log("User: " + user.name);
    return fetchPosts(user.id);
  })
  .then(posts => console.log("Posts: " + posts.length))
  .catch(err => console.error("Error: " + err))
  .finally(() => console.log("Done!"));

// Already resolved
let resolved = Promise.resolve(42);
resolved.then(v => console.log(v));  // 42

// Already rejected
let rejected = Promise.reject(new Error("oops"));
rejected.catch(e => console.error(e.message));  // "oops"

// withResolvers — external control
let { promise, resolve, reject } = Promise.withResolvers();

// You control when it resolves
setTimeout(() => resolve("done"), 1000);
promise.then(console.log);  // "done" after 1 second
